#ifndef KITE_WIND_RENDER_PROTO_H
#define KITE_WIND_RENDER_PROTO_H

// AI: below section was generated by an AI
// Version-2 render response decoder (contracts/device/render.proto). nanopb callbacks write each
// list element straight into fixed arrays; nothing is allocated and no response buffer is needed.
// decode() checks everything one response can prove on its own. validateLamps() checks the lamps
// against the definition that will be in effect, so it runs at activation.

#include <stddef.h>
#include <stdint.h>
#include "nanopb/pb_decode.h"

namespace KiteWindProto {

constexpr uint32_t CONTRACT_VERSION = 2;
constexpr size_t MAX_RESPONSE_BYTES = 4096;  // the maximal sample is about 3.4 KiB
constexpr uint8_t MAX_TRACKS = 26;
constexpr uint16_t MAX_SEGMENTS = 256;
constexpr uint8_t MAX_LAMPS = 51;
constexpr uint8_t FIRST_PIXEL = 1;
constexpr uint8_t LAST_PIXEL = 51;
constexpr uint32_t MAX_DURATION_MS = 60000;
constexpr uint32_t MAX_PERCENT = 100;
constexpr uint32_t MAX_RGB = 0xFFFFFF;
constexpr size_t DIGEST_BYTES = 32;

enum class Curve : uint8_t { Constant = 0, Linear = 1, Cosine = 2 };
enum class Weather : uint8_t { Ok = 0, Unavailable = 1, Simulated = 2 };

enum class Error : uint8_t {
  Ok = 0,
  TooLarge,         // body above MAX_RESPONSE_BYTES
  Malformed,        // protobuf framing, wrong digest length, or the stream ended early
  UnsupportedVersion,
  BadDigest,        // digest missing (all zero)
  TooManyTracks,
  TooManySegments,
  TooManyLamps,
  BadCurve,
  BadTrackShape,    // zero segments, constant track not exactly one, counts do not add up
  OutOfRange,       // duration, percent, rgb, weather or brightness
  PixelOutOfRange,
  DuplicatePixel,
  BadTrackRef,      // lamp track outside the definition in effect
  NoDefinition,     // activation only: no definition held or sent
  DigestMismatch,   // activation only: definition omitted but digest differs from the active one
};

const char* errorName(Error e);

struct Segment {
  uint16_t durationMs;  // 1..60000
  uint8_t from;         // percent
  uint8_t to;
};

struct Track {
  Curve curve;
  uint16_t firstSegment;
  uint16_t segmentCount;
};

// About 1.2 KiB; the player keeps two.
struct Definition {
  uint8_t trackCount;
  uint16_t segmentCount;
  Track tracks[MAX_TRACKS];
  Segment segments[MAX_SEGMENTS];
};

struct Lamp {
  uint8_t pixel;
  uint8_t track;
  uint8_t r, g, b;
};

struct Frame {
  uint32_t contractVersion;
  uint8_t digest[DIGEST_BYTES];
  bool hasDefinition;
  Weather weather;
  uint8_t brightness;
  uint8_t lampCount;
  Lamp lamps[MAX_LAMPS];
};

// Decodes one whole response. `staged` receives the definition when present (trackCount 0
// otherwise). On error the outputs are unusable and must not be activated.
Error decode(pb_istream_t* stream, Frame& frame, Definition& staged);
Error decodeBuffer(const uint8_t* data, size_t length, Frame& frame, Definition& staged);
Error validateLamps(const Frame& frame, const Definition& inEffect);

// A callback stream limited to `length` bytes (the HTTP Content-Length).
pb_istream_t streamFrom(bool (*read)(pb_istream_t*, pb_byte_t*, size_t), void* state, size_t length);

}  // namespace KiteWindProto
// AI: end

#endif
